// colormap_tables.h: the built-in colormap tables of the graphics layer, ids 0 to 15.
//
// Generated by colormap_tables_gen.py; do not edit by hand. Ids 0 to 2 (viridis, magma, rdbu)
// come from caliper_host::colormap_lut, and id 3 (greys) is the grey ramp. Ids 4 to 15 are
// the tables below, in the order of the spec's name table: cividis, inferno, plasma, turbo,
// twilight, coolwarm, batlow, vik, roma, oslo, lajolla, berlin.
//
// Sources: cividis, inferno, plasma, turbo, twilight and coolwarm come from matplotlib 3.11.2.
// batlow, vik, roma, oslo, lajolla and berlin come from the cmcrameri package 1.8, which
// ships the Scientific Colour Maps. Each map is sampled at 256 evenly
// spaced points, i / 255 for i in 0 to 255. Each channel is rounded to 8 bits with round
// half to even. An entry packs r | g << 8 | b << 16 | 0xff << 24.
#pragma once

